package java.util;
public class TreeSet<E> extends AbstractSet<E> implements NavigableSet<E>,Cloneable,java.io.Serializable {
 private final NavigableMap<E,Object> m; private static final Object PRESENT=new Object();
 public TreeSet(){this(new TreeMap<E,Object>());} public TreeSet(Comparator<? super E> c){this(new TreeMap<E,Object>(c));} public TreeSet(Collection<? extends E> c){this();addAll(c);} public TreeSet(SortedSet<E> s){this(s.comparator());addAll(s);} private TreeSet(NavigableMap<E,Object> m){this.m=m;}
 public int size(){return m.size();}public boolean isEmpty(){return m.isEmpty();}public boolean contains(Object o){return m.containsKey(o);}public boolean add(E e){return m.put(e,PRESENT)==null;}public boolean remove(Object o){return m.remove(o)!=null;}public void clear(){m.clear();}public Iterator<E> iterator(){return m.navigableKeySet().iterator();}public Iterator<E> descendingIterator(){return m.descendingKeySet().iterator();}public Comparator<? super E> comparator(){return m.comparator();}public E first(){return m.firstKey();}public E last(){return m.lastKey();}public E lower(E e){return m.lowerKey(e);}public E floor(E e){return m.floorKey(e);}public E ceiling(E e){return m.ceilingKey(e);}public E higher(E e){return m.higherKey(e);}public E pollFirst(){Map.Entry<E,Object> e=m.pollFirstEntry();return e==null?null:e.getKey();}public E pollLast(){Map.Entry<E,Object> e=m.pollLastEntry();return e==null?null:e.getKey();}public NavigableSet<E> descendingSet(){return new TreeSet<E>(m.descendingMap());}public NavigableSet<E> subSet(E a,boolean ai,E b,boolean bi){return new TreeSet<E>(m.subMap(a,ai,b,bi));}public NavigableSet<E> headSet(E b,boolean bi){return new TreeSet<E>(m.headMap(b,bi));}public NavigableSet<E> tailSet(E a,boolean ai){return new TreeSet<E>(m.tailMap(a,ai));}public SortedSet<E> subSet(E a,E b){return subSet(a,true,b,false);}public SortedSet<E> headSet(E b){return headSet(b,false);}public SortedSet<E> tailSet(E a){return tailSet(a,true);}public Object clone(){return new TreeSet<E>(this);}
}
